-- Independent Dadyoom teaching supports, not claims about the contents of official books.
-- Idempotent: update only genuinely empty published lessons; add each origin/type once.
DO $dadyoom$
DECLARE
  r RECORD;
  target_id uuid;
  target_content text;
BEGIN
  FOR r IN SELECT * FROM jsonb_to_recordset('[{"n":1,"skill":"الاستثناء بإلا وأركانه","passage":"في «حضر الطلابُ إلا طالبًا» الجملة تامة مثبتة، و«طالبًا» مستثنى منصوب بعد «إلا». تختلف أحكام المستثنى في الجمل المنفية والتامة والناقصة، فلا يُعمم النصب من المثال الأول على كل تركيب.","prompt":"ما إعراب «طالبًا» في الجملة التامة المثبتة؟","correct":"مستثنى منصوب","w1":"فاعل مرفوع","w2":"مبتدأ مرفوع","w3":"بدل مجرور","practice":"أنشئ ست جمل للاستثناء بإلا في صور مختلفة، ثم بين المستثنى منه والحكم الإعرابي وسبب الاختيار."},{"n":2,"skill":"الاستثناء بغير وسوى","passage":"«حضر الطلابُ غيرَ طالبٍ» في تركيب تام مثبت؛ «غيرَ» مستثنى منصوب وهو مضاف، و«طالبٍ» مضاف إليه مجرور. تحمل «سوى» وظيفة قريبة في الاستثناء مع أحكامها الصرفية والإعرابية بحسب الموقع.","prompt":"ما إعراب «طالبٍ» بعد «غيرَ»؟","correct":"مضاف إليه مجرور","w1":"مفعول به","w2":"خبر مرفوع","w3":"حال","practice":"اكتب أربع جمل بغير وسوى، ثم أعرب أداة الاستثناء وما بعدها مع مراعاة نوع الجملة."},{"n":3,"skill":"الاستثناء بخلا وعدا","passage":"«حضرَ المشاركونَ خلا طالبًا» يجوز في تركيب معروف نصب الاسم بعد «خلا» على المفعولية إذا عُدّت فعلًا، وقد يجر إن عُدت حرف جر في بعض الاستعمالات. يوضح ذلك اختلاف التحليل بحسب وجه استعمال الأداة.","prompt":"أي تفسير يجيز جر الاسم بعد «خلا»؟","correct":"عدّ خلا حرف جر","w1":"اعتبارها ضميرًا","w2":"جعل الاسم مبتدأ","w3":"جعلها أداة نداء","practice":"أنشئ أربعة تراكيب بخلا وعدا مع بيان الوجه الإعرابي ومتى يجوز النصب أو الجر."},{"n":4,"skill":"تصغير الاسم ودلالته","passage":"من الأوزان الشائعة للتصغير «فُعَيْل»، مثل «كُتَيِّب» تصغير «كتاب» وفق التحولات الصرفية المناسبة، وقد يفيد الصغر أو التودد أو غيرهما بحسب السياق. لا يصح أخذ التصغير دلالة سلبية ثابتة.","prompt":"ما تصغير «كتاب» في الاستعمال الشائع؟","correct":"كُتَيِّب","w1":"كاتِب","w2":"مكتوب","w3":"كتابة","practice":"صغر سبعة أسماء مناسبة، ثم بين الوزن والغاية الدلالية في جملتين مختلفتين."},{"n":5,"skill":"القصر وتخصيص الحكم","passage":"في «ما النجاحُ إلا ثمرةُ المثابرة» يوجد قصر بالنفي والاستثناء في سياق بلاغي يجعل المثابرة أساسًا للنجاح، ولا يلزم منه نفي كل سبب آخر خارج المقام. القصر توجيه للمعنى يعتمد على المقصود والسياق.","prompt":"أي تركيب يفيد القصر بالنفي والاستثناء؟","correct":"ما النجاح إلا ثمرة المثابرة","w1":"نجح الطالب","w2":"هل جاء الطالب؟","w3":"ليت النجاح قريب","practice":"اكتب ثلاثة أمثلة للقصر، وبين المقصور والمقصور عليه وعلاقة المعنى بالسياق."},{"n":6,"skill":"طرق القصر المتنوعة","passage":"من طرق القصر النفي والاستثناء مثل «ما جاء إلا خالدٌ»، واستخدام «إنما» مثل «إنما العلمُ بالتعلّم»، والتقديم لغرض الاختصاص في مقامات مناسبة. تختلف درجة الحصر المقصود بحسب القرائن.","prompt":"ما أداة القصر في «إنما العلم بالتعلم»؟","correct":"إنما","w1":"إلا وحدها","w2":"لا الناهية","w3":"يا النداء","practice":"كوّن جملتين لكل طريق من طرق القصر المدروسة، ثم وضح ما قُصر على ماذا دون إطلاق أحكام عامة."},{"n":7,"skill":"الحال وصاحبها","passage":"في «دخل الطالبُ مبتسمًا» «مبتسمًا» حال منصوبة تبين هيئة الطالب عند الدخول وصاحب الحال «الطالبُ». تختلف الحال عن النعت من حيث المعنى وأحكام المطابقة والتعريف في المثال التعليمي.","prompt":"ما وظيفة «مبتسمًا» في المثال؟","correct":"حال منصوبة","w1":"فاعل","w2":"مفعول به","w3":"مضاف إليه","practice":"اكتب خمس جمل بأحوال مفردة، وحدد صاحب الحال وعلامة النصب وأثر حذف الحال على المعنى."},{"n":8,"skill":"تعدد الحال لصاحب واحد","passage":"«عاد المتعلمُ مسرورًا مطمئنًا» يحتمل وجود حالين مفردتين منصوبتين لصاحب حال واحد «المتعلم» تصفان هيئتين متلازمتين في الموقف. يحتاج التحليل التأكد أن الكلمتين ليستا صفتين لاسم آخر في السياق.","prompt":"كم حالًا في «عاد المتعلم مسرورًا مطمئنًا»؟","correct":"حالان","w1":"لا حال","w2":"حال واحدة بالضرورة","w3":"ثلاثة أحوال","practice":"أنشئ أربع جمل فيها حالان لصاحب واحد أو أحوال لأصحاب مختلفين، ثم حدد العلاقة بدقة."},{"n":9,"skill":"الجملة الواقعة حالًا","passage":"في «دخل الرجلُ وهو يبتسم» جملة «وهو يبتسم» في محل نصب حال، وتشتمل على رابط هو واو الحال وضمير يعود إلى صاحبها. تختلف عن الحال المفردة «مبتسمًا» رغم تشابه الوظيفة الدلالية.","prompt":"ما وظيفة جملة «وهو يبتسم»؟","correct":"جملة حالية","w1":"مفعول به مباشر","w2":"فاعل","w3":"بدل مطابق","practice":"حوّل ثلاث أحوال مفردة إلى جمل حالية صحيحة مع بيان الرابط وصاحب الحال."},{"n":10,"skill":"رابط الجملة الحالية","passage":"قد ترتبط الجملة الحالية بصاحبها بالضمير أو واو الحال أو بهما بحسب بنيتها، مثل «وصل الطالبُ وكتابه في يده» حيث تربط الواو والضمير الجملة بصاحبها. ينبغي النظر إلى الجملة كاملة قبل تحديد الرابط.","prompt":"ما الرابط الظاهر في «وصل الطالب وكتابه في يده»؟","correct":"واو الحال والضمير","w1":"أداة الاستثناء","w2":"اسم التفضيل","w3":"لام التعليل","practice":"أنشئ خمس جمل حالية موزعة على أنواع الروابط، ثم حدد كل رابط وصاحب الحال."},{"n":11,"skill":"النسب إلى الأسماء","passage":"تتكون ياء النسب المشددة في أمثلة مثل «بحرينِيّ» للدلالة على الانتساب إلى البحرين، مع مراعاة التغييرات الصرفية المناسبة لأصل الاسم. لا تُضاف الياء دون النظر إلى شكل الكلمة المنسوب إليها.","prompt":"ما اللاحقة الدالة على النسب في «بحرينيّ»؟","correct":"ياء النسب المشددة","w1":"تاء التأنيث","w2":"ألف التثنية","w3":"نون التوكيد","practice":"انسب إلى عشرة أسماء متنوعة، ثم اشرح مواضع التغيير الصرفي ومثالًا له في جملة."},{"n":12,"skill":"النسب إلى فعيل وفعيلة","passage":"يتطلب النسب إلى أسماء على وزن فعيل وفعيلة مراعاة قواعد الألفاظ وحروفها الأصلية وصيغتها، ولا يجوز اختراع قاعدة واحدة تنطبق على كل الأسماء. في «مدينة» نستعمل «مَدَنيّ» مع تغيرات صرفية تاريخية، وهو مثال يُستفاد منه في المقارنة.","prompt":"ما الصيغة الشائعة للنسب إلى «مدينة»؟","correct":"مَدَنيّ","w1":"مدينتان","w2":"مدينيون دائمًا","w3":"مدينةً","practice":"راجع ست كلمات على وزني فعيل وفعيلة في مرجع صرف موثوق، واكتب نسبتها مع شرح التغيير."},{"n":13,"skill":"الجناس التام وغير التام","passage":"الجناس تشابه بين لفظين واختلاف في المعنى، والتام يستوفي جوانب التشابه الصوتي والكتابي المعتبرة، وغير التام ينقصه بعض ذلك. في «صلّيتُ المغربَ في المغربِ» إذا قصد بالأول الصلاة وبالثاني البلد جناس تام بين لفظين مختلفَي المعنى في السياق.","prompt":"ما الفارق العام بين الجناس التام وغير التام؟","correct":"درجة تماثل اللفظين مع اختلاف المعنى","w1":"وجود الضد فقط","w2":"تشابه المعنى دائمًا","w3":"أن أحدهما فعل بالضرورة","practice":"اكتب مثالين لجناس تام وآخرين لغير التام من مصادر واضحة، وفسر المعنيين ووجه الشبه."},{"n":14,"skill":"التمييز وإزالة الإبهام","passage":"في «اشتريتُ عشرين كتابًا» تمييز العدد «كتابًا» منصوب يوضح المعدود، وفي «ازداد الطالب علمًا» تمييز نسبة منصوب يوضح وجه الزيادة. يحدد السياق نوع التمييز ولا تُعد كل نكرة منصوبة تمييزًا.","prompt":"ما إعراب «كتابًا» في «عشرين كتابًا»؟","correct":"تمييز منصوب","w1":"حال","w2":"فاعل","w3":"مضاف إليه","practice":"صغ ست جمل فيها تمييز ذات ونسبة، مع ضبطه وإعرابه وبيان الإبهام الذي رفعه."},{"n":15,"skill":"السجع والانسجام الصوتي","passage":"السجع توافق أواخر الفواصل في النثر مع مراعاة المعنى، مثل الجملة التدريبية «العلمُ نورٌ والعملُ سرورٌ» إذا استعملت في سياق مناسب. لا يجعل السجع العبارة صحيحة أخلاقيًا أو علميًا بمجرد جرسها.","prompt":"ما الذي يميز السجع في النثر؟","correct":"توافق الفواصل صوتيًا","w1":"التضاد فقط","w2":"تكرار حرف جر","w3":"وجود فعلين متضادين","practice":"اكتب فقرة قصيرة بفاصلتين مسجوعتين دون تكلف، ثم وضح كيف يخدم الإيقاع المعنى."}]'::jsonb) AS x(
    n integer,skill text,passage text,prompt text,correct text,w1 text,w2 text,w3 text,practice text
  ) LOOP
    SELECT l.id,l.content INTO STRICT target_id,target_content
    FROM public.lessons l
    JOIN public.units u ON u.id=l.unit_id
    JOIN public.grades g ON g.id=u.grade_id AND g.grade_number=11
    JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027' AND cu.id='79a8732d-6a86-46cd-8cad-31673af20a0c'
    JOIN public.countries c ON c.id=cu.country_id AND c.code='BH'
    WHERE u.title='نحو 212 — شرح ابن عقيل وتيسير الصرف والمنار' AND u.semester=2 AND l.sort_order=r.n AND l.status='published'
    FOR UPDATE OF l;
    IF char_length(coalesce(target_content,''))<350 THEN
      UPDATE public.lessons SET
        content='ضاديوم — إثراء مستقل أصلي للصف الثامن، الفصل الثاني. لا يمثل النص الوزاري الأصلي ولا يثبت مطابقة العنوان للمصدر.'||E'\n\n'||
          'المهارة: '||r.skill||E'\n\n'||
          'النموذج التعليمي والشرح: '||r.passage||E'\n\n'||
          'أهداف التعلم: يحدد المتعلم شاهدًا صحيحًا ويشرح دلالته، ويميّز بين الفكرة والدليل، ثم ينتج كتابة مناسبة للمهارة.'||E'\n\n'||
          'سؤال الفهم: '||r.prompt||E'\n\n'||
          'التطبيق الكتابي: '||r.practice||E'\n\n'||
          'التمايز: المبتدئ يحصل على كلمات مفتاحية وبداية جملة؛ المتوسط يجيب بدليل مستقل؛ المتقدم يقارن بين صياغتين ويبرر تحسيناته.'||E'\n\n'||
          'مراجعة المعلم: تحقق من صحة الاستدلال والإملاء وعلامات الترقيم والترابط. لا تُمنح درجة جودة تلقائية لمجرد تسليم المهمة.'||E'\n\n'||
          'تنبيه المصدر: راجع العنوان المستورد والكتاب الرسمي قبل وصف هذا التدريب بأنه مطابق للمنهج.'||E'\n\n'||'المدخل السابق المحفوظ: '||coalesce(target_content,''),
        updated_at=now()
      WHERE id=target_id;
    END IF;
    IF EXISTS (SELECT 1 FROM public.lessons WHERE id=target_id AND content LIKE 'ضاديوم — إثراء مستقل أصلي للصف الثامن%') THEN
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'فهم النص الإثرائي','multiple_choice','assessment',r.prompt,
        jsonb_build_object('origin','DADYOOM_BH_RELIGIOUS_G11_T2_NAHW212_ORIGINAL_20261008','notOfficialBook',true,'ocrReview','pending','options',CASE (r.n % 4) WHEN 0 THEN jsonb_build_array(r.correct,r.w1,r.w2,r.w3) WHEN 1 THEN jsonb_build_array(r.w1,r.correct,r.w2,r.w3) WHEN 2 THEN jsonb_build_array(r.w1,r.w2,r.correct,r.w3) ELSE jsonb_build_array(r.w1,r.w2,r.w3,r.correct) END),
        jsonb_build_object('correct',r.correct),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='multiple_choice' AND content->>'origin'='DADYOOM_BH_RELIGIOUS_G11_T2_NAHW212_ORIGINAL_20261008');
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'كتابة تطبيقية بمراجعة المعلم','writing','practice',r.practice,
        jsonb_build_object('origin','DADYOOM_BH_RELIGIOUS_G11_T2_NAHW212_ORIGINAL_20261008','notOfficialBook',true,'humanReviewRequired',true,'text',r.practice,'skillQualityAutoVerified',false),
        jsonb_build_object('grading_mode','completion_only_reference','model_answer','لا تكفي المطابقة النصية؛ يصحح المعلم ملاءمة الأفكار والدليل والترابط.'),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='writing' AND content->>'origin'='DADYOOM_BH_RELIGIOUS_G11_T2_NAHW212_ORIGINAL_20261008');
    END IF;
  END LOOP;
END
$dadyoom$;